head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vScrenID = "ULDSTF45001.xml";
scwin.clickIsuCd;
scwin.clickIsuKorAbbrv;
scwin.procJob;
scwin.pJobTitl = js_jobtitl;
scwin.pMngId = js_id;
scwin.fr_SecuGrpId = SECUGRP_ID_EW;
scwin.fr_MktId = $c.lc.fn_getMktId();
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.getStrtDate = function() {
    var yyyymmdd = edt_TASK_DD.getValue();
    var yyyy = yyyymmdd.substring(0, 4);
    var mm = yyyymmdd.substring(4, 6);
    var dd = yyyymmdd.substring(6, 8);
    if (mm == 01) {
        mm = 12;
        yyyy = yyyy - 1;
    } else {
        mm = mm - 1;
    }
    return '' + yyyy + $c.ut.cGetZero(mm, 2) + dd;
};
scwin.getListDate = function() {
    var yyyymmdd = edt_TASK_DD.getValue();
    var yyyy = yyyymmdd.substring(0, 4);
    var mm = yyyymmdd.substring(4, 6);
    var dd = yyyymmdd.substring(6, 8);
    if (mm == 02) {
        mm = 12;
        yyyy = yyyy - 1;
    } else if (mm == 01) {
        mm = 11;
        yyyy = yyyy - 1;
    } else {
        mm = mm - 2;
    }
    return '' + yyyy + $c.ut.cGetZero(mm, 2) + dd;
};
scwin.fn_list_sync1 = function() {
    var url = "/listingCommon.do?SCREN_ID=ULDSTF45001.gfm&SCREN_PROCES_TP_CD=01&method=listGeneralForDynamicName" + "&outputMessageId=ELW_DELIST_CAUTN" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwdelistcaunt.select.prelpclose.condition";
    url += "&{P}PROC_DD=" + edt_TASK_DD.getValue();
    url += "&{P}STRT_DD=" + edt_STRT_DD.getValue();
    url += "&{P}LIST_DD=" + edt_LIST_DD.getValue();
    url += "&{P}ISUR_CD=" + cmd_Isur_Cd.BindColVal;
    url += "&{P}LP_MBR_NO=" + cmd_liqu_lpNm.BindColVal;
    dts_List_1.DataID = encodeURI(url);
    dts_List_1.reset();
    $c.cm.ShowWin(grd_List_1);
};
scwin.fn_list_sync2 = function() {
    var url = "/listingCommon.do?SCREN_ID=ULDSTF45001.gfm&SCREN_PROCES_TP_CD=01&method=listGeneralForDynamicName" + "&outputMessageId=ELW_DELIST_CAUTN" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwdelistcaunt.select.lpclose.condition_list";
    url += "&{P}PROC_DD=" + edt_TASK_DD.getValue();
    url += "&{P}STRT_DD=" + edt_STRT_DD.getValue();
    url += "&{P}LIST_DD=" + edt_LIST_DD.getValue();
    url += "&{P}ISUR_CD=" + cmd_Isur_Cd.BindColVal;
    url += "&{P}LP_MBR_NO=" + cmd_liqu_lpNm.BindColVal;
    dts_List_2.DataID = encodeURI(url);
    dts_List_2.reset();
    $c.cm.ShowWin(grd_List_2);
};
scwin.fn_set_isurcode = function() {
    dts_ElwInst.DataID = "/CodeAction.do?method=listWrntCd&For=R";
    dts_ElwInst.Reset();
};
scwin.fn_set_liqucode = function() {
    dts_LpMbrNo.DataID = "/CodeAction.do?method=listLeadCom&For=R";
    dts_LpMbrNo.Reset();
};
scwin.fn_setContnId = function(obj) {
    scwin.clickIsuCd = dts_List_1.getCellData(eval(obj), "ISU_CD");
    scwin.clickIsuKorAbbrv = dts_List_1.getCellData(eval(obj), "ISU_KOR_ABBRV");
};
scwin.fn_CheckForm = function() {
    if (edt_TASK_DD.text.length != 8) {
        $c.win.alert("[마감일]을 정확히 입력하세요.");
        return false;
    }
    if (edt_STRT_DD.text.length != 8) {
        $c.win.alert("[1개월 거래량 산정기간 시작일]을 정확히 입력하세요.");
        return false;
    }
    if (edt_LIST_DD.text.length != 8) {
        $c.win.alert("[상장제한일]을 정확히 입력하세요.");
        return false;
    }
    return true;
};
scwin.fn_setDate = function() {
    var url = "/listingCommon.do?SCREN_ID=ULDSTF45001.gfm&SCREN_PROCES_TP_CD=01&method=listGeneralForDynamicName" + "&outputMessageId=CODE_M_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwdelistcaunt.select.date";
    url += "&{P}DATE1=" + scwin.getStrtDate();
    url += "&{P}DATE2=" + scwin.getListDate();
    dts_date.DataID = encodeURI(url);
    dts_date.reset();
    for (var i = 1; i <= dts_date.getTotalRow(); i++) {
        if (dts_date.getCellData(i, 'CD_ID') == '1') {
            edt_STRT_DD.setValue(dts_date.getCellData(i, 'VALUE'));
        } else if (dts_date.getCellData(i, 'CD_ID') == '2') {
            edt_LIST_DD.setValue(dts_date.getCellData(i, 'VALUE'));
        }
    }
};
scwin.btn_Search_onclick = function() {
    if (scwin.fn_CheckForm()) {
        if (img_Elwlist.getSelectedTabIndex() == 1) {
            scwin.fn_list_sync1();
        } else if (img_Elwlist.getSelectedTabIndex() == 2) {
            scwin.fn_list_sync2();
        } else {
            $c.win.alert('오류가 발생하였습니다. 담당자에게 연락 하시기 바랍니다.');
        }
    }
};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.dts_ElwInst_OnLoadError = function() {
    $c.stf.alert_error(dts_ElwInst);
};
scwin.dts_LpMbrNo_OnLoadError = function() {
    $c.stf.alert_error(dts_LpMbrNo);
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    edt_TotalCnt_1.setValue("총 " + dts_List_1.getTotalRow() + "건");
    $c.cm.CloseWin(rowcount, grd_List_1);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    edt_TotalCnt_2.setValue("총 " + dts_List_2.getTotalRow() + "건");
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_set_isurcode();
    scwin.fn_set_liqucode();
    if (scwin.fr_MktId != '9') {
        $c.stf.showObj(img_TASK_DD, false);
        $c.stf.showObj(img_STRT_DD, false);
        $c.stf.showObj(img_LIST_DD, false);
    }
    edt_TASK_DD.setValue($c.ut.cGetToday("yyyymmdd"));
    edt_END_DD.setValue(edt_TASK_DD.getValue());
    scwin.fn_setDate();
    scwin.fn_list_sync1();
};
scwin.img_Excel1_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (dts_List_1.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd_List_1, $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "거래부진으로 인한 상장폐지 우려 종목", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.img_Excel2_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (dts_List_2.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd_List_2, $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "거래부진으로 인한 상장폐지 대상 종목", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.img_Elwlist_OnSelChanged = function(nIndex) {
    if (nIndex == 1) {
        scwin.fn_list_sync1();
    } else if (nIndex == 2) {
        scwin.fn_list_sync2();
    }
};
scwin.img_STRT_DD_onclick = function() {
    popUpCalendar2(edt_STRT_DD);
};
scwin.img_LIST_DD_onclick = function() {
    popUpCalendar2(edt_LIST_DD);
};
scwin.edt_TASK_DD_OnKillFocus = function() {
    scwin.fn_setDate();
    edt_END_DD.setValue(edt_TASK_DD.getValue());
};
scwin.img_TASK_DD_onclick = function() {
    popUpCalendar2(edt_TASK_DD);
};
